CREATE TABLE devices (device_id TEXT PRIMARY KEY,name TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),config_revision INTEGER NOT NULL DEFAULT 1 CHECK(config_revision>0),updated_at INTEGER NOT NULL);
CREATE TABLE device_screens (device_id TEXT NOT NULL REFERENCES devices(device_id),screen_id TEXT NOT NULL,position INTEGER NOT NULL CHECK(position BETWEEN 0 AND 15),kind TEXT NOT NULL CHECK(kind IN ('pet','quota')),provider_id TEXT REFERENCES provider_config(provider_id),window_id TEXT,PRIMARY KEY(device_id,screen_id),UNIQUE(device_id,position),CHECK((kind='pet' AND position=0 AND screen_id='pet-home' AND provider_id IS NULL AND window_id IS NULL) OR (kind='quota' AND position>0 AND provider_id IS NOT NULL AND window_id IS NOT NULL)));
